insert into demands (id, entidade, necessidade, proposta) values
  (1, 'NTI', 'Solicita cerca de 60 m², preferencialmente próximo ao Espaço Cidades Inteligentes.', 'Estande “Hub 46”, com cápsula imersiva, apresentação de empresas associadas, quiosques rotativos, gamificação, quiz, brindes e mini palestras/pitches.'),
  (2, 'UNIMATER', 'Espaço institucional para cursos, ainda em definição interna.', 'Experiências interativas por curso, como farmácia, biomedicina e demais áreas, além de uma atração central conectada à proposta institucional.'),
  (3, 'SEBRAE', 'Espaços para oficinas, auditório/sala e possíveis atividades vinculadas ao espaço institucional.', 'Trilha de IA, final da Jornada GovTech, Escape Room, Fórum do Ecossistema, comportamento empreendedor para crianças, escalada para jovens e AgroFoodTech.'),
  (4, 'Secretaria de Educação', 'Espaço dentro do eixo de Cidades Inteligentes / Educação.', 'Hackathon, Hackathon de gestores escolares, painel de futuros com produções das crianças e artistas locais, exposição de práticas de computação, Feira do Empreendedorismo/Jovens Empreendedores e Semana Literária no Centro Cultural.'),
  (5, 'IDR-Paraná', 'Solicita área externa, com duas tendas de 10m x 10m, totalizando cerca de 200 m², com água e energia.', 'Óculos 3D, simulador de colheita, colhedora de parcela, mandala de solos, simulador de chuva, automação/leitura NIT, maquete do polo de pesquisa, meliponicultura, sementes, feijão, café/leite e palestra sobre IA e ciência de dados no agro.'),
  (6, 'UTFPR', 'Necessidade de múltiplos espaços, internos e externos, além de algumas atividades na própria UTFPR.', 'Semana Tecnológica integrada à INVENTUM, atividades multidisciplinares, estande dinâmico, rádio/podcast, flashmob, música/dança, desafios de IA, xadrez, lançamento balístico, corrida maluca e seleção de projetos para exposição.'),
  (7, 'NRE', 'Espaço compartilhado para rede estadual e projetos regionais.', 'Apresentação de resultados da educação digital, ferramentas tecnológicas, projetos de escolas integrais, projetos integradores do ensino médio, empregabilidade, vitrine de vagas e aproximação dos estudantes com carreiras tecnológicas.'),
  (8, 'ACEPB', 'Espaço institucional ainda a alinhar.', 'Participação na feira, apoio institucional e possibilidade de colaborar com ações a serem definidas, inclusive articulando com sua estrutura, eventos e empresários associados.');
